<?php
namespace CloudHost247\Ovh\Api;
class CurlTransport implements Transport
{
 public function send($method,$url,array $headers,$body,$connectTimeout,$timeout,$maxBytes){if(!extension_loaded('curl'))throw new ApiException('cURL is required.');$received=0;$response='';$ch=curl_init($url);curl_setopt_array($ch,array(CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$headers,CURLOPT_POSTFIELDS=>$body===''?null:$body,CURLOPT_RETURNTRANSFER=>false,CURLOPT_HEADER=>true,CURLOPT_CONNECTTIMEOUT=>$connectTimeout,CURLOPT_TIMEOUT=>$timeout,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_USERAGENT=>'CloudHost247-OVH/1.0',CURLOPT_WRITEFUNCTION=>function($ch,$chunk)use(&$response,&$received,$maxBytes){$received+=strlen($chunk);if($received>$maxBytes)return 0;$response.=$chunk;return strlen($chunk);}));$ok=curl_exec($ch);$err=curl_error($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$headerSize=(int)curl_getinfo($ch,CURLINFO_HEADER_SIZE);curl_close($ch);if($received>$maxBytes)throw new ApiException('OVH response exceeded the configured size limit.',$status);if(!$ok)throw new ApiException('OVH transport error: '.$err,$status);$rawHeaders=substr($response,0,$headerSize);$payload=substr($response,$headerSize);$retry=0;if(preg_match('/^Retry-After:\s*(\d+)/mi',$rawHeaders,$m))$retry=(int)$m[1];return array('status'=>$status,'body'=>$payload,'retry_after'=>$retry);}
}
